import React from 'react';

function Button({ children, variant = 'primary', onClick, className = '' }) {
    const baseStyles = 'px-6 py-3 rounded-md font-semibold transition-all duration-300';

    const variants = {
        primary: 'bg-teal-700 hover:bg-teal-800 text-white shadow-md hover:shadow-lg',
        secondary: 'bg-white hover:bg-gray-50 text-secondary border-2 border-gray-300 hover:border-gray-400',
    };

    return (
        <button
            onClick={onClick}
            className={`${baseStyles} ${variants[variant]} ${className}`}
        >
            {children}
        </button>
    );
}

export default Button;
